
/* NeuroFix Med v70 — folha de estilos canônica consolidada. */

:root{

  --ink:#101113; --black:#0A0A0A; --paper:#F8F7F3; --surface:#FFFFFF;
  --line:#E8E4DB; --muted:#737373; --gold:#C9A24E; --gold2:#E1C77F;
  --blue:#286ED8; --blue-soft:#EAF2FF; --green:#2D8A63; --green-soft:#EAF7F1;
  --orange:#B66A25; --orange-soft:#FFF3E6; --red:#B94A48; --red-soft:#FFF0EF;
  --shadow:0 18px 50px rgba(31,27,18,.08); --radius:22px;

}

/* — Regra global v73: line-height compacta para textos de legenda/descrição.
   Compensa o body{line-height:1.7} do globals.css nas telas do app. */
.v73-app small {
line-height:1.45
}
.v73-app .note-content,
.v73-app .note-content p,
.v73-app .note-content li,
.v73-app .note-content ul,
.v73-app .note-content ol {
line-height:1.55
}
.v73-app .note-content small {
display:block;line-height:1.45;margin-top:4px
}

.v73-app * {
box-sizing:border-box
}
.v73-app {
scroll-behavior:smooth
}

.v73-app {
margin:0;background:var(--paper);color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-height:100vh
}

.v73-app button, .v73-app input, .v73-app textarea {
font:inherit
}
.v73-app button {
cursor:pointer
}

.v73-app .app {
display:grid;grid-template-columns:260px 1fr;min-height:100vh
}

.v73-app .sidebar {
position:fixed;left:0;top:0;bottom:0;width:260px;background:var(--black);color:#fff;padding:24px 18px;display:flex;flex-direction:column;z-index:50
}

.v73-app .logo-wrap {
height:94px;display:flex;align-items:center;padding:0 14px 18px;border-bottom:1px solid rgba(255,255,255,.1)
}

.v73-app .logo-wrap img {
width:150px;max-height:76px;object-fit:contain;filter:brightness(1.12)
}

.v73-app .nav {
margin-top:18px;display:grid;gap:7px
}

.v73-app .nav button {
border:0;background:transparent;color:#b8b8b8;padding:12px 13px;border-radius:12px;text-align:left;display:flex;align-items:center;gap:11px;font-weight:650
}

.v73-app .nav button:hover, .v73-app .nav button.active {
background:linear-gradient(90deg,rgba(201,162,78,.22),rgba(201,162,78,.06));color:#fff
}

.v73-app .nav button.active {
box-shadow:inset 2px 0 0 var(--gold)
}

.v73-app .nav .ico {
width:20px;text-align:center;font-size:17px
}

.v73-app .sidebar-foot {
margin-top:auto;border-top:1px solid rgba(255,255,255,.1);padding:18px 8px 0
}

.v73-app .profile {
display:flex;align-items:center;gap:10px
}
.v73-app .avatar {
width:38px;height:38px;border-radius:50%;background:linear-gradient(145deg,var(--gold2),#8a6327);display:grid;place-items:center;color:#111;font-weight:900
}

.v73-app .profile small {
display:block;color:#8f8f8f;margin-top:2px
}

.v73-app .main {
grid-column:2;min-width:0
}
.v73-app .topbar {
height:78px;position:sticky;top:0;z-index:30;background:rgba(248,247,243,.9);backdrop-filter:blur(16px);border-bottom:1px solid rgba(218,214,205,.7);display:flex;align-items:center;justify-content:space-between;padding:0 34px
}

.v73-app .breadcrumb {
font-size:13px;color:#777
}
.v73-app .breadcrumb b {
color:#202020
}
.v73-app .top-actions {
display:flex;align-items:center;gap:10px
}
.v73-app .search {
width:300px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:10px 14px;display:flex;gap:8px;align-items:center
}
.v73-app .search input {
border:0;outline:0;width:100%;background:transparent
}
.v73-app .icon-btn {
border:1px solid var(--line);background:#fff;width:42px;height:42px;border-radius:13px
}

.v73-app .content {
padding:30px 34px 60px;max-width:1460px;margin:0 auto
}
.v73-app .page {
display:none;animation:fade .25s ease
}
.v73-app .page.active {
display:block
}
@keyframes fade{
from{
opacity:.2;transform:translateY(5px)
}
.v73-app to {
opacity:1;transform:none
}

}

.v73-app .hero {
min-height:275px;border-radius:28px;overflow:hidden;background:radial-gradient(circle at 88% 30%,rgba(44,110,216,.42),transparent 25%),linear-gradient(135deg,#0b0d11,#151b25 65%,#0a0a0a);color:#fff;position:relative;padding:38px 42px;display:flex;align-items:center;box-shadow:var(--shadow)
}

.v73-app .hero:after {
content:"";position:absolute;inset:0;background-image:linear-gradient(90deg,rgba(10,10,10,.08) 0%,rgba(10,10,10,.15) 48%,rgba(10,10,10,.72) 100%),url(data:image/jpeg;base64,);background-size:auto,46%;background-repeat:no-repeat;background-position:right center;opacity:.72;mix-blend-mode:screen;pointer-events:none
}

.v73-app .hero-copy {
position:relative;z-index:2;max-width:675px
}
.v73-app .eyebrow {
color:var(--gold2);text-transform:uppercase;letter-spacing:.16em;font-weight:800;font-size:11px
}
.v73-app .hero h1 {
font-family:Georgia,"Times New Roman",serif;font-weight:500;font-size:44px;line-height:1.06;margin:10px 0 14px
}
.v73-app .hero p {
font-size:16px;line-height:1.6;color:#d0d4dc;max-width:620px
}
.v73-app .btn {
border:0;border-radius:13px;padding:12px 17px;font-weight:800;display:inline-flex;align-items:center;gap:9px
}
.v73-app .btn-primary {
background:linear-gradient(135deg,var(--gold2),var(--gold));color:#17120a
}
.v73-app .btn-secondary {
background:#fff;color:#111;border:1px solid var(--line)
}
.v73-app .btn-dark {
background:#111;color:#fff
}
.v73-app .hero-actions {
display:flex;gap:10px;margin-top:22px
}

.v73-app .kicker {
display:flex;align-items:end;justify-content:space-between;margin:34px 0 16px
}
.v73-app .kicker h2 {
font-size:22px;margin:0
}
.v73-app .kicker p {
margin:5px 0 0;color:var(--muted);font-size:14px
}
.v73-app .text-link {
border:0;background:transparent;color:var(--blue);font-weight:800
}

.v73-app .grid {
display:grid;gap:18px
}
.v73-app .grid-3 {
grid-template-columns:repeat(3,1fr)
}
.v73-app .grid-4 {
grid-template-columns:repeat(4,1fr)
}

.v73-app .card {
background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:0 8px 24px rgba(31,27,18,.035)
}

.v73-app .continue-card {
padding:22px;display:grid;grid-template-columns:72px 1fr auto;gap:17px;align-items:center
}
.v73-app .subject-icon {
width:64px;height:64px;border-radius:18px;display:grid;place-items:center;background:linear-gradient(145deg,#172740,#2b70db);color:white;font-size:28px;box-shadow:inset 0 0 0 1px rgba(255,255,255,.15)
}

.v73-app .continue-card h3 {
margin:0 0 5px;font-size:18px
}
.v73-app .meta {
color:var(--muted);font-size:13px
}
.v73-app .progress {
height:7px;border-radius:10px;background:#eceae5;overflow:hidden;margin-top:12px
}
.v73-app .progress span {
display:block;height:100%;background:linear-gradient(90deg,var(--gold),var(--blue));border-radius:inherit
}

.v73-app .subject-card {
padding:20px;min-height:170px;position:relative;overflow:hidden;transition:.2s
}
.v73-app .subject-card:hover {
transform:translateY(-3px);box-shadow:var(--shadow)
}
.v73-app .subject-card .number {
font-family:Georgia,serif;font-size:46px;color:#ece8dd;position:absolute;right:17px;top:10px
}
.v73-app .subject-card h3 {
margin:17px 0 8px
}
.v73-app .subject-card p {
margin:0;color:var(--muted);line-height:1.45;font-size:13px
}
.v73-app .pill {
display:inline-flex;align-items:center;gap:6px;padding:6px 9px;border-radius:999px;background:#f3f1eb;font-size:11px;font-weight:800;color:#5b5851
}
.v73-app .pill.blue {
background:var(--blue-soft);color:var(--blue)
}
.v73-app .pill.green {
background:var(--green-soft);color:var(--green)
}
.v73-app .pill.gold {
background:#fbf4e3;color:#8b6821
}
.v73-app .pill.red {
background:var(--red-soft);color:var(--red)
}

.v73-app .review-list {
display:grid;gap:10px;padding:12px
}
.v73-app .review-item {
display:grid;grid-template-columns:42px 1fr auto;align-items:center;gap:12px;padding:10px;border-radius:14px
}
.v73-app .review-item:hover {
background:#faf9f6
}
.v73-app .review-dot {
width:38px;height:38px;border-radius:12px;background:var(--blue-soft);display:grid;place-items:center
}
.v73-app .review-item b {
font-size:14px
}
.v73-app .review-item small {
display:block;color:var(--muted);margin-top:3px
}
.v73-app .mini-btn {
border:1px solid var(--line);background:#fff;border-radius:10px;padding:8px 10px;font-weight:750;font-size:12px
}

.v73-app .promise {
padding:26px;display:grid;grid-template-columns:repeat(4,1fr);gap:14px
}
.v73-app .promise-step {
padding:17px;border-left:2px solid var(--gold)
}
.v73-app .promise-step strong {
display:block;margin-bottom:8px
}
.v73-app .promise-step span {
font-size:13px;color:var(--muted);line-height:1.45
}


.v73-app .library-head {
display:flex;align-items:end;justify-content:space-between;margin-bottom:20px
}
.v73-app .library-head h1 {
font:500 38px Georgia,serif;margin:0 0 7px
}
.v73-app .library-head p {
color:var(--muted);margin:0
}
.v73-app .library-layout {
display:grid;grid-template-columns:310px 1fr;gap:20px
}
.v73-app .tree {
padding:16px;position:sticky;top:98px;height:max-content
}
.v73-app .tree h3 {
font-size:13px;text-transform:uppercase;letter-spacing:.1em;color:#777;margin:4px 8px 13px
}
.v73-app .tree-btn {
width:100%;border:0;background:transparent;padding:11px 12px;text-align:left;border-radius:11px;display:flex;justify-content:space-between;align-items:center;color:#505050
}
.v73-app .tree-btn:hover, .v73-app .tree-btn.active {
background:#f3f0e8;color:#111;font-weight:800
}
.v73-app .tree-child {
margin-left:13px;border-left:1px solid var(--line);padding-left:9px
}
.v73-app .topic-panel {
padding:25px
}
.v73-app .topic-panel h2 {
margin:0 0 7px
}
.v73-app .topic-panel>p {
margin:0 0 22px;color:var(--muted)
}
.v73-app .module {
border:1px solid var(--line);border-radius:17px;margin-bottom:12px;overflow:hidden
}
.v73-app .module-head {
padding:16px 18px;background:#fbfaf7;display:flex;align-items:center;justify-content:space-between
}
.v73-app .module-head h3 {
margin:0;font-size:15px
}
.v73-app .topic-row {
display:grid;grid-template-columns:36px 1fr auto;gap:12px;align-items:center;padding:14px 18px;border-top:1px solid var(--line);cursor:pointer
}
.v73-app .topic-row:hover {
background:#fffdf8
}
.v73-app .topic-row .check {
width:28px;height:28px;border-radius:9px;background:#f1efe9;display:grid;place-items:center;color:#8b8b8b
}
.v73-app .topic-row.done .check {
background:var(--green-soft);color:var(--green)
}
.v73-app .topic-row b {
display:block;font-size:14px
}
.v73-app .topic-row small {
color:var(--muted)
}


.v73-app .note-header {
background:#101217;color:white;border-radius:24px;padding:27px 30px;position:relative;overflow:hidden
}
.v73-app .note-header:after {
content:"";position:absolute;right:-70px;top:-80px;width:280px;height:280px;border-radius:50%;background:radial-gradient(circle,rgba(42,111,216,.38),transparent 67%)
}
.v73-app .note-header .crumb {
font-size:12px;color:#aeb4bf
}
.v73-app .note-header h1 {
font:500 38px Georgia,serif;margin:10px 0 7px;position:relative;z-index:2
}
.v73-app .note-header p {
color:#b9bec8;margin:0;position:relative;z-index:2
}
.v73-app .note-tools {
display:flex;gap:9px;position:absolute;right:25px;bottom:24px;z-index:3
}
.v73-app .note-tools button {
border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.07);color:white;border-radius:11px;padding:9px 12px
}
.v73-app .study-path {
display:grid;grid-template-columns:repeat(7,1fr);gap:8px;margin:16px 0 20px
}
.v73-app .path-step {
padding:10px 7px;text-align:center;border-radius:11px;background:#efede7;color:#76736c;font-size:11px;font-weight:800;cursor:pointer
}
.v73-app .path-step.active {
background:var(--black);color:#fff
}
.v73-app .path-step.done {
background:var(--green-soft);color:var(--green)
}

.v73-app .study-layout {
display:grid;grid-template-columns:230px minmax(0,1fr) 280px;gap:19px
}
.v73-app .note-nav, .v73-app .study-side {
position:sticky;top:96px;height:max-content
}
.v73-app .note-nav {
padding:15px
}
.v73-app .note-nav h4, .v73-app .study-side h4 {
font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:#777;margin:4px 8px 12px
}
.v73-app .note-nav button {
width:100%;border:0;background:transparent;text-align:left;padding:11px;border-radius:10px;color:#696969;font-size:13px
}
.v73-app .note-nav button:hover, .v73-app .note-nav button.active {
background:#f1eee6;color:#111;font-weight:800
}
.v73-app .note-content {
padding:31px 37px;min-height:850px
}
.v73-app .note-content h2 {
font:500 31px Georgia,serif;margin:0 0 18px
}
.v73-app .note-content h3 {
margin:29px 0 10px
}
.v73-app .note-content p {
font-size:16px;line-height:1.55;color:#333
}
.v73-app .lead {
font-size:18px!important;color:#212121!important
}
.v73-app .callout {
border-radius:16px;padding:17px 19px;margin:20px 0
}
.v73-app .callout.blue {
background:var(--blue-soft);border-left:4px solid var(--blue)
}
.v73-app .callout.gold {
background:#fbf4e3;border-left:4px solid var(--gold)
}
.v73-app .callout.red {
background:var(--red-soft);border-left:4px solid var(--red)
}
.v73-app .callout.green {
background:var(--green-soft);border-left:4px solid var(--green)
}
.v73-app .callout b {
display:block;margin-bottom:5px
}
.v73-app .key-list {
display:grid;gap:10px;margin:16px 0
}
.v73-app .key-item {
padding:14px;border:1px solid var(--line);border-radius:13px;display:flex;gap:11px;align-items:flex-start
}
.v73-app .key-item span:first-child {
width:28px;height:28px;border-radius:9px;background:#f2efe7;display:grid;place-items:center;flex:0 0 auto;font-weight:900
}
.v73-app .compare {
width:100%;border-collapse:collapse;margin:18px 0
}
.v73-app .compare th, .v73-app .compare td {
padding:13px;border:1px solid var(--line);text-align:left;font-size:14px
}
.v73-app .compare th {
background:#f8f6f0
}
.v73-app .study-side {
padding:15px
}
.v73-app .side-box {
border:1px solid var(--line);border-radius:15px;padding:14px;margin-bottom:12px
}
.v73-app .side-box b {
font-size:13px
}
.v73-app .side-box p {
font-size:12px;color:var(--muted);line-height:1.45
}
.v73-app .checklist label {
display:flex;gap:8px;align-items:flex-start;font-size:12px;margin:10px 0
}
.v73-app .checklist input {
accent-color:var(--green)
}
.v73-app .textarea {
width:100%;min-height:95px;border:1px solid var(--line);border-radius:11px;padding:10px;resize:vertical;outline:0
}
.v73-app .side-actions {
display:grid;gap:8px
}
.v73-app .side-actions .btn {
justify-content:center;font-size:12px
}


.v73-app .question {
border:1px solid var(--line);border-radius:18px;padding:21px;margin:18px 0
}
.v73-app .question .qnum {
color:var(--blue);font-weight:900;font-size:12px
}
.v73-app .question h3 {
font-size:16px;line-height:1.55;margin:8px 0 15px
}
.v73-app .option {
border:1px solid var(--line);border-radius:12px;padding:12px 13px;margin:8px 0;display:flex;gap:10px;align-items:flex-start;cursor:pointer
}
.v73-app .option:hover {
background:#faf9f6
}
.v73-app .option.selected {
border-color:var(--blue);background:var(--blue-soft)
}
.v73-app .option.correct {
border-color:var(--green);background:var(--green-soft)
}
.v73-app .option.wrong {
border-color:var(--red);background:var(--red-soft)
}
.v73-app .feedback {
display:none;border-radius:13px;padding:15px;margin-top:13px;line-height:1.55;font-size:14px
}
.v73-app .feedback.show {
display:block
}
.v73-app .feedback.ok {
background:var(--green-soft);color:#205f45
}
.v73-app .feedback.no {
background:var(--red-soft);color:#7e312f
}


.v73-app .question-correction {
color:#2c2c2c
}
.v73-app .correction-result {
padding:14px 15px;border-radius:12px;margin-bottom:14px
}
.v73-app .correction-result.ok {
background:var(--green-soft);color:#205f45
}
.v73-app .correction-result.no {
background:var(--red-soft);color:#7e312f
}
.v73-app .alternative-review-title {
font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#777;margin:18px 0 12px
}
.v73-app .alternative-review-title>span {
font-size:20px;line-height:1.3;font-weight:900;letter-spacing:0;text-transform:none;color:#202020
}
.v73-app .alternative-review {
display:grid;gap:12px
}
.v73-app .alt-comment {
display:grid;grid-template-columns:38px 1fr;gap:12px;padding:16px 17px;border:1px solid var(--line);border-radius:13px;background:#fff;color:#333
}
.v73-app .alt-comment.correct {
border-color:#83c8a6;background:#f2fbf6
}
.v73-app .alt-comment.selected-wrong {
border-color:#e5aaa6;background:#fff6f5
}
.v73-app .alt-letter {
width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:#f0eee8;font-size:15px;font-weight:900
}
.v73-app .alt-comment.correct .alt-letter {
background:var(--green);color:#fff
}
.v73-app .alt-comment.selected-wrong .alt-letter {
background:var(--red);color:#fff
}
.v73-app .alt-comment p {
margin:0;font-size:16px;line-height:1.72
}

.v73-app .alt-comment-body {
min-width:0;color:#333
}
.v73-app .alt-comment-heading {
display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:9px
}
.v73-app .alt-comment-heading b {
font-size:16px;line-height:1.45
}
.v73-app .alt-comment-topic {
font-size:12px;font-weight:800;color:#6f6758;background:#f4f1ea;border:1px solid #e7e1d5;border-radius:999px;padding:4px 8px
}
.v73-app .alt-explanation {
margin:0;font-size:16px;line-height:1.72
}
.v73-app .alt-learning-point, .v73-app .alt-elimination-tip {
margin-top:11px;padding:12px 13px;border-radius:10px;font-size:15px;line-height:1.68
}
.v73-app .alt-learning-point {
background:#f7f5ef;border:1px solid #e9e4d9
}
.v73-app .alt-elimination-tip {
background:#fff9e9;border:1px solid #ead8a1
}
.v73-app .alt-learning-point b, .v73-app .alt-elimination-tip b {
display:block;margin-bottom:5px;font-size:12px;text-transform:uppercase;letter-spacing:.045em;color:#65542a
}
.v73-app .alternative-review-title {
display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap
}
.v73-app .alternative-review-title small {
display:block;max-width:620px;text-transform:none;letter-spacing:0;font-size:14px;line-height:1.6;color:#666;font-weight:500
}
@media(max-width:760px){
.v73-app .alternative-review-title>span {
font-size:19px
}
.v73-app .alternative-review-title small {
font-size:14px;line-height:1.58
}
.v73-app .alt-comment {
grid-template-columns:36px 1fr;padding:15px 14px;gap:10px
}
.v73-app .alt-comment p, .v73-app .alt-explanation {
font-size:16px;line-height:1.7
}
.v73-app .alt-learning-point, .v73-app .alt-elimination-tip {
font-size:15px;line-height:1.65
}

}

.v73-app .question-takeaway {
margin-top:13px;padding:13px 14px;border-left:4px solid var(--gold);background:#fff8e8;border-radius:10px;color:#5e4b18
}
.v73-app .question-source {
display:block;margin-top:10px;color:#777;font-size:10px
}
.v73-app .oral-review-box {
