/* Reset de heranças do globals.css que sangram dentro do V70. */
.v73-app h1, .v73-app h2, .v73-app h3, .v73-app h4, .v73-app h5, .v73-app h6 {
  color: inherit;
  font-family: inherit;
  font-weight: inherit;
  letter-spacing: normal;
  line-height: inherit;
  margin: 0;
}
.v73-app a { color: inherit; text-decoration: none; }
.v73-app p { color: inherit; margin: 0; }

/* Overrides do layout pai (esconde Sidebar antiga do app quando /dashboard etc. estão montados). */
body.v73-dashboard .app-shell > .sidebar { display: none !important; }
body.v73-dashboard .app-shell {
  display: block !important;
  min-height: 100vh !important;
}
body.v73-dashboard .app-shell > main.main-content,
body.v73-dashboard .app-shell > .main-content {
  display: block !important;
  padding: 0 !important;
  margin: 0 !important;
  max-width: none !important;
  width: 100% !important;
  min-height: 100vh !important;
  background: #F8F7F3 !important;
}
body.v73-dashboard { background: #F8F7F3 !important; }
.v73-app { min-height: 100vh; }
